"""Generate RustKit's lookup table from a local copy of WHATWG entities.json."""
import hashlib
import json
import sys
from pathlib import Path

source = Path(sys.argv[1]).read_bytes()
entities = json.loads(source)
names = sorted(key.removeprefix("&") for key in entities)
lines = [
    "// Generated by scripts/generate_html_entities.py from https://html.spec.whatwg.org/entities.json",
    f"// Source SHA-256: {hashlib.sha256(source).hexdigest()}",
    "// Copyright © WHATWG (Apple, Google, Mozilla, Microsoft). BSD-3-Clause.",
    "// See WHATWG-LICENSE.txt in this directory.",
    f"pub(super) const MAX_NAME: usize = {max(map(len, names))};",
    f"pub(super) const MAX_LEGACY: usize = {max(len(n) for n in names if not n.endswith(';'))};",
    "pub(super) const NAMES: &[(&[u8], &str)] = &[",
]
for name in names:
    assert name.removesuffix(";").isascii() and name.removesuffix(";").isalnum()
    value = "".join(f"\\u{{{cp:x}}}" for cp in entities["&" + name]["codepoints"])
    lines.append(f'    (b"{name}", "{value}"),')
lines.append("];")
target = Path(__file__).resolve().parents[1] / "crates/rustkit-html/src/entities/named.rs"
target.parent.mkdir(exist_ok=True)
target.write_bytes(("\n".join(lines) + "\n").encode("utf-8"))
